#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Read the master product file
const masterFilePath = path.join(__dirname, '..', 'OOTDay', 'products', 'product_master.json');
const outputDir = path.join(__dirname, '..', 'OOTDay', 'products');

console.log('Reading master product file...');
const rawData = fs.readFileSync(masterFilePath, 'utf8');
const products = JSON.parse(rawData);

console.log(`Total products: ${products.length}`);

// Filter products by category
const womenProducts = products.filter(p => p.category === 'women_clothing');
const menProducts = products.filter(p => p.category === 'men_clothing');

console.log(`Women's clothing products: ${womenProducts.length}`);
console.log(`Men's clothing products: ${menProducts.length}`);

// Write women's clothing to file
const womenFilePath = path.join(outputDir, 'women_clothing.json');
fs.writeFileSync(womenFilePath, JSON.stringify(womenProducts, null, 2), 'utf8');
console.log(`✓ Written ${womenProducts.length} products to women_clothing.json`);

// Write men's clothing to file
const menFilePath = path.join(outputDir, 'men_clothing.json');
fs.writeFileSync(menFilePath, JSON.stringify(menProducts, null, 2), 'utf8');
console.log(`✓ Written ${menProducts.length} products to men_clothing.json`);

// Verify the split
const total = womenProducts.length + menProducts.length;
if (total === products.length) {
  console.log(`✓ Verification passed: ${womenProducts.length} + ${menProducts.length} = ${products.length}`);
} else {
  console.error(`✗ Verification failed: ${womenProducts.length} + ${menProducts.length} ≠ ${products.length}`);
  process.exit(1);
}

